  1092	/** @brief Copies a file
  1093	 *
  1094	 * @param src source file path
  1095	 * @param dst destination file path
  1096	 * @retval 0 on success
  1097	 */
  1098	static int
  1099	mat_copy(const char* src, const char* dst)
  1100	{
