  1114	#else
  1115	    in = fopen(src, "rb");
  1116	#endif
  1117	    if ( in == NULL ) {
  1118	        Mat_Critical("Cannot open file \"%s\" for reading.", src);
  1119	        return -1;
  1120	    }
  1121	
  1122	#if defined(_WIN32) && defined(_MSC_VER)
  1123	    {
  1124	        wchar_t* wname = utf82u(dst);
  1125	        if ( NULL != wname ) {
  1126	            out = _wfopen(wname, L"wb");
